INSERT INTO `courses` VALUES (1,'The diploma course is the introductory course in theology. It introduces the students to the various branches of theology with special attention to the Sacred Scripture. The course could be completed with the minimum duration of two semesters.','Diploma in Theology (DTh)','This is a preparatory course to prepare the students for Bachelors Degree in Theology. The course duration is 2 years (4 semesters) Pre-Degree (Plus Two or equivalent) pass is the eligibility condition for admission to the diploma course. The course introduces the fundamental concepts of Philosophy and Theology. The Greek Philosophy, Scholastic Philosophy, Western Philosophy, Indian Philosophy, Modern and contemporary Philosophy are introduced in this course. The traditional dictum that Philosophy is the handmaid ofTheology is esteemed in this<br />approach.<br /><br />\r\n<h4 style=\"text-align: center;\"><span style=\"background-color: #ffffff;\"><strong>General Syllabus of the Diploma Course in Theology</strong></span></h4>\r\nThe diploma course is the introductory course in theology. It introduces the&nbsp;students to the various branches of theology with special attention to the Sacred Scripture. The course could be completed with the minimum duration of two semesters and the maximum of four semesters.<br /><br />\r\n<table style=\"border-collapse: collapse; width: 100%;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 126px;\">\r\n<td style=\"width: 50%; height: 126px;\"><strong>Paper I: The Revealing God</strong><br />01. Introduction to Theology<br />02. HistoryofTheology<br />03. Divine Revelation in Bible and Tradition<br />04. Sacred Scripture (Pentateuch)<br />05. Church History (Arrival of St. Thomas, Life and Rituals of St. Thomas Christians)</td>\r\n<td style=\"width: 50%; height: 126px;\"><br /><strong>Paper II: Church and Theology</strong><br />06. Word of God (Creation Narratives, Paradise, Fall)<br />07. Canon Law (CIC and CCEO, Canons on Sacraments)<br />08. Fundamental Theology (Ecclesiology)<br />09. Moral Theology (Christian Morality, Conscience, Sin)</td>\r\n</tr>\r\n<tr style=\"height: 72px;\">\r\n<td style=\"width: 50%; height: 72px;\"><strong>Paper III: Growing Faith</strong><br />10. Holy Scripture (Synoptic Gospels, Prophets)<br />11. Dogmatic Theology (Holy Trinity, Christo logy)<br />12. Moral Theology (Christian Social teachings)</td>\r\n<td style=\"width: 50%; height: 72px;\"><strong>Paper IV: On the Path of Salvation</strong><br />13. Holy Scripture (The Gospel of John)<br />14. Dogmatic Theology (Eschatology, Mariology)<br />15. Canon Law (Canons on Parish and Marriage)<br />16. Liturgy (Formation of Liturgy, Liturgy of Hours, Liturgical year)<br />17. Church History (Persecution and freedom of the early Church)</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 50%; height: 18px;\"><strong>Paper V: Christian Life</strong><br />18. Sacred Scripture (Wisdom Literature, Pauline Letters)<br />19. Liturgy (Fundamentals of Latin, Syro-Malabar and Syro-Malankara Liturgy)<br />20. Church History (Indian Church History, History of the Church)</td>\r\n<td style=\"width: 50%; height: 18px;\"><strong>Paper VI: Old Testament Theology </strong><br />21. Introduction to Pentateuch<br />22. Jewish Feasts and sacrifices<br />23. Jewish History of Salvation<br />24. Women in the Bible<br />25. Prophetic literature in Bible<br />26. Wisdom Literature<br />27. Biblical Poetry-Psalms</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 50%; height: 18px;\"><br /><strong>Paper VII: NewTestamentTheology</strong><br />28. Synoptic Gospels<br />29. Gospel of John<br />30. Acts of the Apostles<br />31. Pauline Letters<br />32. Letter to the Hebrews<br />33. Universal Letters<br />34. Book of Revelation</td>\r\n<td style=\"width: 50%; height: 18px;\">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>','6 Months','Please contact Alpha Office. (08086312826)','diploma-in-theology-dth-1','user_files/course/a1d325cc29a394ac57a9df196ee8c213.jpg','','','2020-03-19 00:20:34','2025-06-30 04:59:19'),(3,'In the three year Bachelors Program, a broad and gradual elucidation of catholic theology is offered in the form of courses and seminars. The program aim&rsquo;s to equip the student with the competence necessary to reflect in an integrated and systematic fashion on all major branches of Theology. To this end it provides specialized courses in all the principal fields of sacred Theology','Bachelors Degree in Theology (BTh)','Bachelors Degree in Theology comprises of three years, during which the students will be given courses in Sacred Scripture, the various branches of Theology, Canon Law, Liturgy and Spirituality.<br /><br />\r\n<h5><strong>Admission</strong></h5>\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>An applicant must have completed a two years course of Diploma Course in Philosophy.</li>\r\n<li>The applicant must have a working knowledge of Greek, Latin and Syriac so as to be able to translate the N.T. portions, the documents of the Ecclesiastical Magisterium, and the Liturgical and Patristic texts.</li>\r\n<li>The applicants who have completed their studies in other Institutes and Faculties will be admitted after the scrutiny regarding the canonical validity of the corresponding certificates. The judgment of the academic council of the Institute finalises the issue.</li>\r\n</ol>\r\n<h5><strong>Modus Operandi</strong></h5>\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>The academic year is divided into two semesters. At the end of each semester there shall be exams for the subjects taught in the semester. The students will be examined not only on the basis of lectures but also based on the literature related to the subject assigned for private and personal study.</li>\r\n<li>No student shall be allowed to enroll for the examination without the required number of attendance for the contact classes.</li>\r\n<li>The courses are divided into different sections such as: main and subsidiary, obligatory and elective, institutional and special.</li>\r\n<li>The pedagogy of the Institute includes lectures, seminars, reading and evaluation of the books and articles, tutorials, audio visual aids, language lab.</li>\r\n<li>Besides the fundamental themes in main subjects, which may be offered as courses common for all students, further elaborations may be offered according to special orientations like Biblical, Pastoral, Oriental, Patristic, Missiological and Comparative Religious studies.</li>\r\n</ol>\r\n<br />\r\n<h5><strong>Written Thesis for BTh<br /><br /></strong></h5>\r\nAt the beginning of the 5th semester before the 30th of June of the second stage of the Institutional Cycle, students aspiring for the Bachelor Degree in Theology have to select the topic for the thesis, and the professor who will guide the work. The written thesis must be submitted by the 6th semester before the final examination. It must have a minimum of 6000 words and maximum of 10000<br />words.<br /><br />\r\n<h5><strong>Repetition of Examination<br /><br /></strong></h5>\r\nIf anyone fails in a subject, the examination in the respective subject shall be repeated. Such examinations shall be conducted at the beginning of the following semester. The examinations that are deferred for other reasons shall be conducted at the time fixed by the institute. Those who fail in Degree examinations may repeat the examination only once, at the end of the following semester.<br /><br /><br />\r\n<h5><strong>Grading System</strong></h5>\r\n<br /><br />\r\n<table style=\"border-collapse: collapse; width: 100%;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 14.3141%; text-align: center; height: 18px;\">40%</td>\r\n<td style=\"width: 28.7276%; height: 18px; text-align: center;\">Pass Mark</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 14.3141%; height: 18px; text-align: center;\">41%-50%</td>\r\n<td style=\"width: 28.7276%; height: 18px; text-align: center;\">Third Class</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 14.3141%; height: 18px; text-align: center;\">51%-69%</td>\r\n<td style=\"width: 28.7276%; height: 18px; text-align: center;\">Second Class</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 14.3141%; height: 18px; text-align: center;\">70%-84%</td>\r\n<td style=\"width: 28.7276%; height: 18px; text-align: center;\">First Class</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 14.3141%; height: 18px; text-align: center;\">85% and above&nbsp;</td>\r\n<td style=\"width: 28.7276%; height: 18px; text-align: center;\">Distinction</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<br />This marking system corresponds to the traditional Roman system: Pass - 6; second class 7; first class 8; distinction 9-10.<br />In global evaluation the mark is the quotient obtained by dividing the sum total of individual marks by the number of the examinations.','3 Year (6 Semester)','Please contact Alpha Office. (08086312826)','bachelors-degree-in-theology-bth-1','user_files/course/583f2df7513b214da0d804015e1c4161.jpg','','','2020-03-19 01:09:06','2025-06-04 07:13:35'),(4,'Masters Degree in Theology which comprises of two years provides the students with opportunities to specialize in the various branches of theology such as Biblical, Moral and Dogmatic Theology.','Masters Degree in Theology (MTh)','MTh in Theology conducted by Alpha Institute of Theology and Science provides the students with opportunities to specialize in the various branches of theology. The course is intended to train the students for scientific research and prepares them to teach theology, with the specialization in their respective branch of Theology, in seminaries, in institutions of higher learning and Alpha Institute of Theology and Science comprises 2 years of rigorous research and study. The course, which is conducted on a cyclical basis, consists of lectures, tutorial, seminars, field work, learning of foreign languages and the furnishing of a scientific dissertation, which is to be defended at the end of the course. It offers opportunities to the students for personal study and research under the guidance of competent professors. The degrees offered by the institute at the completion of the course qualify candidates for admission to the Doctoral Study in any ecclesiastical faculty<br />of Theology in Indian and abroad.<br /><br /><br />\r\n<h4><strong>Requirements and Conditions<br /><br /></strong></h4>\r\n<h5><strong>1.</strong> Eligibility</h5>\r\nAdmission to the MTh course is open to those who already possess a degree in BTh with at least second class or its equivalent degree in Theology, the eligibility of which will be adjudged by the competent authorities of the Institute. In the latter case, the candidate should pass a qualifying examination conducted by the institute.<br /><br />\r\n<h5><strong>2.</strong> Registration</h5>\r\n<br />\r\n<ul style=\"list-style-type: square;\">\r\n<li>&nbsp;To be registered to Master\'s Degree programme in Spiritual Theology, the candidate has to duly fill-in the application form provide by the Institute.&nbsp;</li>\r\n<li>The duly filled- in application form, affixed with a passport- size photo has to reach the institute latest by 15th May.</li>\r\n<li>Along with the filled-in application form, five more copies of passport size photos are to be included for the office purposes.</li>\r\n<li>In case of the priests and religious, each filled- in application form has to be accompanied by the approval/no-objection letter of the Bishop or the Provincial Superior or the Superior-in-charge.</li>\r\n<li>Photo-copies of all the relevant certificates and mark lists and documents of other studies accomplished have to be submitted at time the of registration.</li>\r\n<li>The registration fee has to be paid at the time of the registration. If it is paid by DD or Cheque, it has to be drawn in favour of Alpha Institute of Theology and Science.</li>\r\n<li>If the registration is done through E-mail or post it has to be addressed to the Director/ Alpha Institute ofTheology and Science.</li>\r\n</ul>\r\n<h5>3. Attendance</h5>\r\nStudents must attend all lectures without neglect, carry out all prescribed academic assignments and participate in the regular activities of the institute. For any period of absence, the Director/Dean of studies is to be informed before-hand. Applications for longer periods of leave duly countersigned by the respective authority is to be made in writing to the Director/Dean of Studies at least 3 days in advance.<br /><br />\r\n<h5>4. Seminars</h5>\r\nIn addition to the above- mentioned courses students are expected to present two scientific papers as part of seminars during the course of their research. The seminars are conducted on relevant topics that are not included in the regular academic programme. Experts on the theme will be invited to give input talks and orientation. The topic would be suggested to the students by the academic board after sufficient consultations and study. Each seminar would be equal to a two credit course.<br /><br />\r\n<h5>5. Foreign Languages</h5>\r\nEvery MTh student is expected to have the basic knowledge in at least two of the classic languages of Hebrew, Greek, Syriac and Latin and one of the modern languages, such as, German , Spanish, Italian or French . Mastery of these languages is expected to enable students to have a direct access to the sources and to help them widen the horizon of their original thinking. Alpha Institute of<br />Theology and Science provides the opportunity for learning the foreign languages.<br />\r\n<h5><br />6. Evaluation of the Course</h5>\r\ni. Examinations will be held for every course taught. Normally examinations are held at the end of each semester. If circumstances require, at the discretion of the Director and Dean of the institute, examinations may also take place at other periods.<br /><br />ii. Examinations may be oral or written, with or without a certain percentage of marks allotted to a written assignment or an internal assessment (at the discretion of the individual professor). For any change in the schedule of the exams, the permission of the director and dean of Studies have to be sought.<br /><br />iii. No student will be allowed to repeat an examination if he/she has passed with low marks in a subject. The students who fail in one or<br />more subjects are to repeat the same in the second session of examination sat the beginning of the following semester.The dates of the<br />second session of examinations will be intimated by the Dean. Maximum of only 69% can be awarded in the second session.\r\n<h5><br />7. Comprehensive Examination</h5>\r\nMasters Degree in Theology (MTh) comprises of Specialized studies and research work in various branches of theology and allied sciences. Its duration is of four semesters (2 Years) at the end of which there will be comprehensive examination leading to MTh degree.\r\n<h5><br />8. Dissertation</h5>\r\na. The Dissertation or the Scientific Research Pa performs a major scheme of the Master\'s Degree in Theology. Through the Scientific Research paper the student is not only introduced into the art of scientific presentation of a theme, but also helped to specialize in a field of interest within the scope of the specific branch of Theology. The research will be done under the guidance of a qualified professor, who would constantly accompany the student through his/her expertise, timely evaluations and corrections.<br /><br />b. The candidate has to register his topic of dissertation by submitting to the Dean/Registrar the duly filled-in form of registration after having obtained the signature of his/her moderator.<br /><br />c. Dissertation should be typed in white paper of good quality and sufficient opacity. All sheets of paper used should be of the same quality. Manifold paper should not be used.<br /><br />d. An \"A4\" size paper should be used for dissertation. The text of the dissertation should be typed with 1.5\" line spacing, except in the case where quotations are given in indent. A space of 1.5\" on the left margin and a space of 1\" on the right margin should be kept. A space of 1\" should be kept on the top and the bottom of the page. Dissertation should be typed only on one side of the paper.<br /><br />e. The dissertation should be of minimum 100 pages and maximum 140 pages. The above- mentioned page limit includes the bibliography and the appendices.<br /><br />f. students have to submit 3 copies of the dissertation to the Dean one month prior to the defense (one month of Institute working days).<br /><br />g. The cover page shall have the format approved by the Institute.<br /><br />h.&nbsp; &nbsp;A dissertation submitted without observing the above-mentioned requirements will not be accepted.\r\n<h5><br />9. The public defense</h5>\r\nUpon submission of the dissertation, the Head of the department (Director)/ Dean of studies shall fix the moderators and finalise the date of defense after consulting the Registrar. The public defense of the dissertation, lasting an hour, will take place before a board of two examiners, who will be the first and the second moderators. The defense can take place only when all the other requirements for the respective degree have been fulfilled.\r\n<h5><br />10. Grading System<br /><br /></h5>\r\n<table style=\"border-collapse: collapse; width: 58.4493%; height: 103px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 46.6203%; height: 18px; text-align: center;\">40%</td>\r\n<td style=\"width: 36.2823%; height: 18px; text-align: center;\">&nbsp;Pass Mark</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 46.6203%; height: 18px; text-align: center;\">41%-50%</td>\r\n<td style=\"width: 36.2823%; height: 18px; text-align: center;\">Third Class</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 46.6203%; height: 18px; text-align: center;\">51%-69%</td>\r\n<td style=\"width: 36.2823%; height: 18px; text-align: center;\">Second Class</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 46.6203%; height: 18px; text-align: center;\">70%-84%</td>\r\n<td style=\"width: 36.2823%; height: 18px; text-align: center;\">First Class</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 46.6203%; height: 18px; text-align: center;\">85%&nbsp;&nbsp;and above</td>\r\n<td style=\"width: 36.2823%; height: 18px; text-align: center;\">Distinction</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<br />This marking system corresponds to the traditional Roman system: Pass-6; second class 7; first class 8; distinction 9-10.<br />In global evaluation the mark is the quotient obtained by dividing the sum total of individual marks by the number of the examinations.<br /><br /><br />\r\n<h3><strong>MTh - Biblical Theology (Syllabus)</strong></h3>\r\n<br />\r\n<p><strong>Specialization Courses<br /></strong><br />&bull; Social Justice in Bible<br />&bull; Gospel of John: Thematic Study<br />&bull; Apocryphal Books: Historical - Critical Analysis<br />&bull; Paul as a Pastoral Theologian in Corinthian Correspondences<br />&bull; Patristic Exegesis<br />&bull; Hebrew Poetry- Psalms<br />&bull; Book of Revelation: Hermeneutical Issues<br />&bull; Concept of God in Wisdom Literature<br />&bull; Understanding OT as a Prophetic Literature<br />&bull; Ecclesiology of the Universal Letters<br />&bull; Historical Approaches in the Bible<br />&bull; New Trends in Hermeneutics<br /><br /><strong>General Courses<br /></strong><br />&bull; Philosophy and Theology<br />&bull; Spiritual Theology<br />&bull; Uniqueness of Christ in the Theology of Other Religion<br />&bull; Modern Trends in the Morality of Life<br />&bull; Historical Evolution and Trends of Modern Missiology<br />&bull; Special Questions in Christology<br />&bull; Modern Trends in Theological Anthropology<br /><br /><strong>Language Courses<br /></strong><br />&bull; Biblical Greek II<br />&bull; Biblical Hebrew II - Readings<br />&bull; Syriac Language: A window to Eastern Churches<br />&bull; Latin<br /><br /><strong>Assignments &amp; Dissertation<br /></strong><br />&bull; Passover and Paschal Lamb Imagery in the Gospel of John<br />&bull; An Exegetical Analysis of a Psalm<br />&bull; Salient Features of Verbum Domini<br />&bull; Dei Verbum<br />&bull; MTh Dissertation</p>','2 Years (4 Semester)','Please Contact Alpha Office (08086312826)','masters-degree-in-theology-mth-1','user_files/course/36bbeb8f44b87d3cca2a203bd9eb94a4.jpg','','','2020-03-19 03:28:56','2025-06-04 07:15:43'),(6,'The research programme is oriented to assist competent students to make personal contribution to scientific and theological research through completion of the research program and the writing of a dissertation, which is to be accomplished under the guidance of a competent professorial staff, within a reasonable time-limit. The research degree (DRS) obtained at the completion of the programme is awarded under the competency of Alpha Institute.','RESEARCH IN RELIGIOUS SCIENCE (DRS)','<h4 style=\"text-align: center;\"><strong>Aim of the Research Programme</strong></h4>\r\n<br /><strong>&sect;1</strong>. The research programme is oriented to assist students to make personal contribution to scientific and theological research through the writing of a dissertation, which is to be accomplished under the guidance of a competent professorial staff, within a reasonable time-limit.<br /><br /><strong>&sect;2</strong>. The candidates study in depth and specialize in one specific theme, without neglecting the over- all comprehension and mastery of the vast field of theology.<br /><br /><strong>&sect;3</strong>. The research programme will be especially geared toward preparing a research dissertation, within a reasonable timeframe. The dissertation should constitute an innovative contribution to the area of theological research.<br /><br />\r\n<h4 style=\"text-align: center;\"><strong>Modus Operandi<br /><br /></strong></h4>\r\n<strong>&sect;1</strong>. The Research Programme in Theology consists of an interrelated and coherent combination of educational and other study activities.&nbsp;<br /><br /><strong>&sect;2</strong>. The Research Programme consists of obligatory and optional elements which aim at broadening knowledge and experience by way of methodological reflection, systematic guidance, discussion with other doctoral students, contact with professors from one\'s own area of research, the presentation of research results, international contacts, preparation of publications, supplementary formation through the study of languages and other specialised courses, and team work.<br /><br /><strong>&sect;3</strong>. Participation in the Research Programme is a compulsory condition for obtaining the research degree. As a rule, this implies a residency requirement of two years of full time study. In very exceptional cases candidates may be exempted from the requirement to participate in the Research Programme. In such cases an alternative assignment will be imposed.<br /><br /><br />\r\n<h4 style=\"text-align: center;\"><strong>Eligibility<br /><br /></strong></h4>\r\nIn principle, admission to the Research in Religious Science demands a valid Master\'s Degree in Theology (MTh) with at least a high second class, the validity of which will be adjudged by the competent authorities of the Institute. In case of necessity, the student should pass a qualifying examination conducted by the Institute.<br /><br /><strong>&sect;1</strong>. Candidates, who meet the following conditions for admission, may be admitted to the research programme in Theology conducted by the Alpha Institute:<br />\r\n<ol>\r\n<li><span style=\"text-align: justify;\">The candidate has obtained the degree of Research Master of Advanced Studies in Theology and Religion awarded by the Alpha Institute of Theology and science. A candidate who has obtained an equivalent Masters degree in Theology from another Indian or a foreign university may also be admitted to the research programme in theology. Such applications are assessed by the&nbsp;research committee.&nbsp;</span>The committee evaluates the content of the various course components of the second-cycle degree that the applicant followed. Should it become evident that the said programme is not equivalent to that required for the Research Master of Advanced Studies in Theology offered by the Institute, no direct admission to the research programme in theology will be granted.</li>\r\n<li>The candidate can present adequate study results and has obtained at least 50% for the whole of the master programme(s) and a level of 70% for the Research Paper.</li>\r\n<li>During the assessment of the application for admission, the total period of time the student needed to obtain the study points for the master programme(s) is also taken into account.</li>\r\n<li>The candidate submits a research project in the field of theology which (a) fits into the research profile of the Faculty ofTheology and Religious Studies, (b) is accepted by a supervisor (and/or co-supervisor) belonging to the Faculty of Alpha Institute, (c) and is approved by the concerned research unit of the Faculty of Alpha Institute.</li>\r\n</ol>\r\n<br /><strong>&sect;2</strong>. Besides English, the Research Candidates should have an advanced knowledge of the classical languages, such as Hebrew, Greek and Latin as may be required by the nature of the research and also a working knowledge of at least one of the modern languages, such as, German, Spanish, Italian or French.<br /><br /><strong>&sect;3</strong>. Candidates are required to submit a detailed research project- on the form provided for this purpose and signed by the supervisor - to the research secretariat before the dates indicated on the faculty calendar of the year in which they wish to be admitted to the Research programme.<br />\r\n<ol>\r\n<li>During the first two weeks of June/September, the members of the tenured academic personnel of the research units will evaluate whether the proposed projects fit into the research profile of the research unit. Particular attention should be paid to methodological skills, including the research student\'s capacity to read the primary literature necessary for his/her research in its original language.</li>\r\n<li>The coordinator of the research unit sends the results of the assessment to the research committee. The research committee considers these findings and decides whether the submitted research projects meetthe requirements.</li>\r\n<li>The Secretary of the Research Committee stores a copy of the proposed project, signed by the Research Unit\'s coordinator, the promoter (and, if necessary, co-promoter) and the candidate, in the candidate\'s file.</li>\r\n</ol>\r\n<br /><strong>&sect;4</strong>. Those who have obtained a Masters Degree in Theology from another Indian or a foreign university may also be admitted to the Research&nbsp;Programme in Theology provided they meet the conditions for admission outlined above. Applications are assessed by the Research&nbsp;Committee, whose composition is constituted according to the regulations of the Faculty. The Committee evaluates the content of the various course components of the second-cycle degree that the applicants followed. Should it become evident that the said programme is not equivalent to that required for the Master of Advanced Studies in Theology and Religion offered by Alpha Institute, no direct admission to the Research&nbsp;Programme in Theology will be granted. The Committee then passes the file on to the Faculty Admissions Committee.<br /><br /><br />\r\n<h4 style=\"text-align: center;\"><strong>Duration</strong></h4>\r\nResearch Students require spending at least four semesters (two years) in research work, in regular contact with the Institute. The duration of the research programme may be extended up to seven years, in which case starting from the fourth year, registration should be renewed. At the end of this period of seven years, the student loses his/her registration. He/ She cannot re-register for another term with the same topic of dissertation.<br /><br /><br />\r\n<h4 style=\"text-align: center;\"><strong>Promoters</strong></h4>\r\n<br />Depending on the nature of the research, the Board, if it deems it necessary, can suggest the second promoter already at the time of the registration of the topic. The first promoter should be a qualified member of the faculty of the Institute or any eligible professor approved by the Institute.<br /><br /><strong>&sect;1</strong>. The promoter forms the pivot of the research&nbsp;training, in which the research student\'s research project occupies a central position. As such, he or she is responsible for the material and intellectual climate in which the research student develops and carries out his or her research. The role of the supervisor is therefore not limited to the initiation of the research. He or she also plays a stimulating, coordinating and evaluating role throughout the research process. The supervisor must also ensure that the research student can acquire other skills in the context of his or her training that are essential to enabling him or her to switch smoothly to another position after the research training,<br />inside or outside the academic world.<br /><br /><strong>&sect;2</strong>. A good supervisor possesses the necessary qualities to ensure the correct guidance and support of each of his or her research students:<br />\r\n<ol>\r\n<li>The supervisor is an active researcher and has acquired a sound reputation. This can be deduced, for example, depending upon his or her length of academic service and the research domain, from academic publications, citations, invitations to contribute to conferences and the acquisition of significant research financing.</li>\r\n<li>The supervisor has built up his or her reputation in a research domain that is sufficiently related to the field in which the research student is carrying out his or her research to enable him or her to give the requisite supervision.</li>\r\n<li>The supervisor is responsible for the quality of the research plan of the research student.</li>\r\n</ol>\r\n<br /><br /><strong>&sect;3</strong>. The supervisor provides intensive supervision. The supervision ensures that there is adequate provision for the research studentto consult with qualified researchers about the planning, execution and results of the research. Research units and supervisors consult on how the research student can receive effective and high quality supervision. Regular formal and informal contacts between the research student, the supervisor and the supervisory team form the basis of good supervision. The contacts between the research student and the supervisor are set out in the work arrangements that are made fol lowing the annual appraisal interviews.<br /><br /><strong>&sect;4</strong>. The specific tasks of the supervisor and the supervisory team are:<br />\r\n<ol>\r\n<li>to help the research student in the planning, execution and, if necessary, the adaptation of the research.</li>\r\n<li>to help the research student to place the research in a broader context,</li>\r\n<li>to assist the research student in the interpretation and analysis of the results obtained from his or her research.</li>\r\n<li>to encourage the research student in presenting his or her work by regularly attending presentations and giving the research student feedback on his or her performance.</li>\r\n<li>to introduce the research student into the research world<br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(i) by involving him or her in the research of the research group<br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(ii) by bringing him or her into contact with other researchers within the research domain,<br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; e.g. by encouraging active participation in conferences or by a stay in another research institution.</li>\r\n<li>to encourage the research student to publish his or her work, point out publication opportunities and assist in preparing publications. The supervisor and the supervisory team bear an important joint responsibility for the research process and also for the publications arising from the research. They give the research student the maximum opportunity to valorize the work performed as the first author listed on publications.</li>\r\n</ol>\r\n<br /><br /><strong>&sect;5</strong>. The supervisor creates a research environment in which the integrity of academic practice (e.g. good data management, responsible authorship, ... ) is the norm. In addition, the supervisor clarifies what is to be regarded as lack of the integrity of academic conduct within the context of the research domain<br /><br />\r\n<ol>\r\n<li>The supervisor draws up jointly with the research student a schedule for the research training. The supervisor informs the research student about the training on offer at the Alpha Institute and discusses with the research student the content of the research training. The supervisor further draws the research student\'s attention to interesting possibilities for taking up additional training or education both within and outside the ALPHA INSTITUTE. The supervisor ensures (together with the dean or head of department) that the research student\'s teaching commitments and other tasks are so organised that the completion of the research within the anticipated time limit is not put at risk.</li>\r\n<li>The supervisor is jointly responsible for the efficient progress of the research process. The supervisor encourages the research student to finalise his or her research within a reasonable term.</li>\r\n<li>The supervisor is jointly responsible for creating a pleasant professional work environment. This means, inter alia, that account is taken of personal factors that can have an impact on the research.</li>\r\n</ol>\r\n<br /><br /><strong>&sect;6</strong>. A proactive attitude is expected of the research student. It is the research student him or herself in the first instance who develops his or her research and it is the research student who is expected to contribute increasingly actively to the planning of the research and the interpretation and analysis of the results as the research progresses. He or she also ensures that any problems are communicated as quickly as possible (to the supervisor and the supervisory team in the first instance) so that an appropriate solution can be sought. The development of a proactive work attitude and of the necessary skills to think and communicate about problems with a view to solving them is essential to enabling the student to develop into an independent researcher. The supervisor therefore encourages the research student to develop these skills.<br /><br /><br /><strong>&sect;7</strong>. The (faculty) research committees vouch, in collaboration with the supervisors and the supervisory committees, for the admission and/or follow-up of research students. The quality of the supervisor must therefore be a point of special interest for these committees. Supervisors can be helped to adjust how they carry out their supervision with the advice of the committee and in consultation with all concerned.<br />Participation In the first year of the research the student is to attend the Methodology Seminar and the Inter-Disciplinary seminar organized by the Institute and validate the specialized courses prescribed by his/her promoter in consultation with the concerned Head of the Department. Research Students have to participate in all the research program organized by Alpha Institute. These program are aimed at extending the candidate\'s knowledge and experience through-in -depth and scientific methodological training, systematic guidance, discussion with fellow researchers, consultation with professors in their areas of specialization, presentation of the results of research, publications and the development of further progressive skills through workshops, learning of source languages and hermeneutic and analytic intellectual pursuits. Participation in the research progrm is a sine qua non for obtaining the Research in theology. The work can be done in the form of courses, seminars or paper of specialization determined by the concerned departments.<br /><br /><br />\r\n<h4 style=\"text-align: center;\"><strong>Progress Reports</strong></h4>\r\n<strong>&sect;1</strong>. The first progress report takes place at the latest one year after the start of the research period and consists of an oral or written presentation on the research undertaken or still to be done. The results determine whether the research programme and the preparation for the thesis can be continued or not. The evaluation takes place on the basis of two criteria: (1) the progress made in the research, and (2) the advances made in academic ability and research maturity by the researcher.<br /><br /><strong>&sect;2</strong>. Subsequently, the researcher reports on an annual basis on the progress of the research.<br /><br /><strong>&sect;3</strong>. Every progress report is validated by the supervisor and any co-supervisors, and assessed by the other members of the supervisory committee. The result is substantiated and recorded in writing and sent to the researcher and the research committee.<br /><br /><strong>&sect;4</strong>. Each year, before the date indicated on the calendar of the Institute, the researchers submit to the supervisory committee a progress report (on the standard form) signed by the researcher and the supervisor. The progress report of the first, the third, and subsequent years will be sent to the supervisory committee for evaluation and approval. On the dates indicated on the faculty calendar, the members of the supervisory committee discuss the progress of each researcher and report their recommendations to the chair oft he research committee.<br /><br />\r\n<ol>\r\n<li>If the supervisor, the supervisory committee, or the research committee find that the research work has made insufficient progress, the research committee holds an evaluation of the relevant research project. The chair of the committee invites the supervisor(s) (and, if necessary, co-supervisor(s) and the members of the supervisory committee to take part in the discussion. The research committee can decide not to renew the permission to register for the research programme.</li>\r\n<li>The research committee can also conclude that the progress report is missing. In that case, the researcher is given two weeks to remedy the situation. After two weeks the chair of the research committee verifies if the researcher concerned has rectified the situation. If this is not the case, permission to re-register cannot be given.</li>\r\n</ol>\r\n<br /><strong>&sect;5</strong>. Two years after starting a research an officially organized evaluation of the progress of the research must take place. This evaluation is undertaken by the members of the supervisory committee. As a rule, for the second year evaluation, the researchers must also submit a chapter of their research dissertation for assessment by the supervisory committee. A meeting takes place with the researchers and their<br />supervisory committees on the date indicated in the faculty calendar. During this meeting the researchers give a short explanation regarding their research and the members of the supervisory committee have the opportunity to ask the researchers questions about the chapters submitted and the general progress of their work. After having heard the researchers, the committee members deliberate and<br />come to one of the following evaluations: good, sufficient with certain recommendations, or inadequate. In the case of \"inadequate\", the research committee is to hold an interim evaluation of the relevant research project. The chair of the research committee invites the supervisor(s) (and, if necessary, co-supervisor(s)) and the other members of the supervisory committee to take part in the discussion. The research committee can decide not to renew the permission to register for the research program.<br /><br />\r\n<h4 style=\"text-align: center;\">Research Program</h4>\r\n<strong>&sect;1</strong>. The research programme is obligatory and must be successfully completed before the researcher is permitted to submit the thesis and defend it publicly.<br /><strong>&sect;2</strong>. The research programme consists of a truncus communis (see art. 15) and a supplementary part (see art. 16). The researcher can only complete the research programme if all the elements of the Common Mandatories (truncus communis) are completed. The research committee can on an individual basis grant a (partial) exemption of the research programme or set a substitute assignment, on the basis of a<br />motivated application by the researcher and in consultation with the supervisor. If the research is multi- and/or interdisciplinary, the research committee can give permission for elements of the truncus communis (see ARTICLE 9) to be replaced by course components from another research programme, on the basis of a motivated application by the researcher in consultation with the supervisor.<br /><strong>&sect;3</strong>. The researcher reports to the&nbsp;research committee on the progress made within his/her research programme. On the basis of this report, the research committee will decide whether the researcher has completed the research programme.<br /><br /><br /><br />\r\n<div style=\"text-align: center;\"><strong>Content of the truncus communis<br /><br /><br /></strong></div>\r\n<strong>&sect;1</strong>. The truncus communis consists of at least the following elements:<br /><br />\r\n<ol>\r\n<li>The writing of at least one scientific publication at an international level or a similar achievement at an international level. By a publication at international level is meant: a peer-reviewed contribution (journal article, contribution to a book, conference proceedings, patent, design) about his/her own research and written in the language of the discipline. The contribution is aimed at an international audience. In order to be able to successfully complete the research programme, the contribution must be published or be accepted for publication,</li>\r\n<li>Giving at least two seminars, either about his/her own research, or on a more general theme,</li>\r\n<li>Giving at least one oral or poster presentation at an international scientific conference,</li>\r\n<li>following at least one seminar series or course component specifically organised for researchers,</li>\r\n<li>Following the course component \'Scientific integrity for starting research\' during the first year of the research programme. Following the course component \'Scientific Integrity for starting research\' is mandatory for researchers.</li>\r\n<li>Reporting on the progress of the research as specified in ARTICLE</li>\r\n</ol>\r\n<strong>&sect;2</strong>. The executive committees can add more specific provisions or additional components to the truncus communis in their Particulars:<br />\r\n<ol>\r\n<li>&nbsp;Researchers attend, during their programme, the compulsory info and formation sessions organized by the research committee for all students. Those unable to attend are expected to inform the chair oft he research committee.</li>\r\n<li>Research courses, courses and seminars on the research level with evaluation (max. four)</li>\r\n</ol>\r\n<strong><br />&sect;3</strong>.Research in Religious Science: each year each specialization/major organizes one research course for the research programme. In the first and second year of his/her research programme, the researcher is obliged to successfully follow the research course organized for his/her specialization/major. If he/she has already followed this course, he/she can propose to the secretary of the research committee to replace that course by a research course taken from the Research Master of Advanced Studies in Theology and Religion* to meet this obligation. A researcher who is immediately admitted to the research programme must follow, in addition to the two research courses organised by<br />his/her specialization/major, two supplementary courses from the Research Master of Advanced Studies in Theology and Religion (proposal to be submitted to the secretary of the research committee). All (research) courses have to be successfully followed (including examinations) before they can be counted towards the completion of the research programme. Exceptions to this rule can only be granted by the research<br />committee. Requests for any exception(s) must be submitted to the secretary of the research committee before October 5.<br /><br /><br /><strong>&sect;4</strong>. The researcher can, in connection with his/her own research project, include a maximum of two other research courses or advanced language courses from the Research Master in Advanced Studies in Theology and Religion in his/her programme.&nbsp;The research committee decides if the&nbsp;aforementioned courses/seminars meet the required research level and must give permission for inclusion of these into the research programme.<br /><br /><br /><strong>&sect;5</strong>. Researchers admitted to the research programme become full members of the research unit that has accepted their research project (Judeo-Christian Scripture Studies, Systematic Theology and Study of Religions, Theological and Comparative Ethics, History of Church and Theology, or Pastoral and Empirical Theology). As members of a research unit, candidates participate in the meetings to which they are invited. Those unable to attend are expected to inform the coordinator of the research unit. They are also expected to participate in the conferences and lectures organized by their own research unit and to report on their participations in the yearly progress report.<br /><br />\r\n<h4 style=\"text-align: center;\"><strong>Thesis</strong></h4>\r\n<br />The thesis is an exam piece that must allow the examination committee to assess the quality of the research.<br /><br /><strong>&sect;1</strong> The regulations with regard to thesis copyright must be respected. The regulations on intellectual property rights on research results including copyright applies, and non-salaried researchers must sign a written agreement at the beginning of their research as specified in this regulation if the results of the research have to be protected.<br /><br /><strong>&sect;2</strong> Language and form of the dissertation<br />Researchers enrolled for the research programme can write their dissertation in English, Malayalam or other Indian Languages. The research committee can give permission for the dissertation to be written in other foreign languages. The length of the dissertation must be appropriate to the topic that it treats. As a rule, topics must be selected in such a way that they can be treated in a scholarly way in no more than 175,000 words (including footnotes). Well-motivated exceptions, when supported by the research unit, can be approved by the research committee.<br /><br /><strong>&sect;3</strong>. It is also permitted to defend a research on the basis of a series of articles accepted and/or published in International journals. In this case, one must however make sure that there is a thematic unity, made explicit in an extensive introduction and/or conclusion, and that the length complies with the general expectations for a research dissertation.<br /><br /><strong>&sect;4</strong>. The Dissertation should be typed in white paper of good quality and sufficient opacity. All sheets of paper used should be of the same quality. Manifold paper should not be used. An \"A4\" size paper should be used for dissertation. The text of the dissertation should be typed with 1.5\" line spacing, except in the case where quotations are given in indent. A space of 1.5\" on the left margin and a space of 1\" on the right margin should be kept. A space of 1\" should be kept on the top and the bottom of the page. Dissertation should be typed only on one side of the paper. The cover page shall have the format approved by the Institute. The detailed description of the methodology to be used in research dissertation is available in the handbook Methodological Guidelines for Research Dissertations published by the Alpha lnsitute and made available on our website (alphathalassery.org). A dissertation, which is submitted without following the prescribed requirements, will not be accepted.<br /><br /><br />\r\n<h4 style=\"text-align: center;\">Submission of the research dissertation</h4>\r\n<br /><br /><strong>&sect;1</strong>. Researchers who fulfil the following requirements may submit the manuscript of their research dissertation:<br />\r\n<ol>\r\n<li>&nbsp;A. Research&nbsp;in Reliogious Science: They have been holders of the academic degree of Research Master of Advanced Studies in Theology and Religion for at least two years, or were granted direct admission by the faculty to the research programme.</li>\r\n<li>Those who have successfully completed the prescribed research programme of the faculty.</li>\r\n<li>Those who have submitted their publications by means of verifying the copy rights ..</li>\r\n</ol>\r\n<strong>&sect;2</strong>. A hard copy of the unbound manuscript of the dissertation is to be submitted to the research secretariat; moreover, an electronic copy is submitted to the research secretariat for the systematic monitoring of plagiarism. Every dissertation is screened for plagiarism with the help of a plagiarism control system.<br /><br /><strong>&sect;3</strong>. Within two weeks after the submission of the dissertation, the researcher submits, with the approval of his/her supervisor, a summary of (maximum) 500 words at the research secretariat. The summary will present the research in a clear and easily accessible manner. In addition to the summary the researcher will submit a maximum of three main theses in which the main results of the research research are summarized. In addition, one or (maximum) two theses are to be added that demonstrate the significance of the dissertation for theology/religious studies as a whole, for domains outside of the area of specialization of the dissertation, for other<br />sciences, or for the church and/or society. All theses together are not to exceed 200 words. The administrative secretary will, after verification of the make-up and the size of these texts, immediately distribute these to the members of the examination committee.<br /><br /><strong>&sect;4</strong>. <strong><em>Report of the Reading Committee</em>:</strong> A copy of the unbound manuscript of the dissertation accompanied by a letter from the Dean and/or Vice-Dean for Research with the submission date for the reading report is sent to the members of the examination committee.<br />\r\n<ol>\r\n<li>The administrative secretary sends a message to the members of the examination committee with a series of proposed dates for the meeting of the examination committee and-on the condition of\'placet\' -possible dates for the defence.</li>\r\n<li>Within six weeks after the constitution of the examination committee, vacation periods excluded, the members of the examination committee submit a written evaluation of the dissertation and the theses to the research secretariat for the attention of the chair of the examination committee. For this they use the guidelines provided to them by the research secretariat. Vacation times include Christmas vacation and the period from the conclusion of the second ordinary examination period to the beginning of the third ordinary examination period. If due to exceptional circumstances, the need arises to deviate from this procedure, a request for an exception to the rule has to be submitted to the research committee, which will reach a decision on the matter.</li>\r\n<li>The members of the examination committee each, independently of one another, write a report according to the faculty guidelines and explicitly mention a motivated final assessment (placet, placet iuxta modum or non placet nisi corrigatur). All members of the examination committee are expected to electronically submit their evaluation report on the dissertation, before the stated deadline, to the research secretariat for the attention of the chair of the examination committee. After all reports have been received, these are sent electronically by the research secretariat to all members of the examination committee including the chair.</li>\r\n</ol>\r\n<h4 style=\"text-align: center;\">Evaluation by the examination committee</h4>\r\n<strong>&sect;1</strong>. The members of the committee first briefly discuss their evaluation reports. Then the researcher is invited to join the committee. The committee members present their questions and objections to him/her, and the candidate is given the opportunity to respond. After this, the committee deliberates, without the presence of the researcher, on the evaluation. Placet means that the dissertation is accepted for defence. Placet iuxta modum means that the dissertation is, in principle, accepted for the defence, but a number of corrections must first be made. Non placet nisi corrigatur means that the dissertation will only be accepted for defence on the condition that the researcher thoroughly revises the dissertation according to the requirements set out in writing by the examination committee.<br /><br /><strong>&sect;2</strong>. Whenever it is deemed appropriate, the chair will consult the members of the committee on the desirability of the (form of the) manuscript\'s publication. Then the chair will examine whether or not the results of the research can be made available for research-PR and scientific communication. When the latter is the case, the research secretariat will take all steps deemed appropriate, in consultation with the student and the supervisor.<br /><br /><strong>&sect;3</strong>. The examination committee\'s evaluation of the dissertation is communicated in the following way:<br />\r\n<ol>\r\n<li>Placet: In the case of a placet, the chair of the committee receives the researcher, together with the supervisor (s) at the end of the predefense, and reports on the decision of the examination committee. The supervisor(s) provide(s) the candidate, within three days, with a summary report explaining the committee\'s decision. The candidate is free to follow suggestions made by the examination committee before submitting the bound copies of the dissertation.</li>\r\n<li>Placet iuxta mod um: In case of placet iuxta mod um, the supervisor(s) provide(s) the candidate, within three days, with a written summary report explaining the decision and summarizing the required modifications. When the candidate is of the opinion that the revised dissertation meets the stated requirements, he/she resubmits, with the written agreement of the supervisor(s) (and, if necessary, the co-supervisor(s)), within a maximum period of three weeks, the revised part/parts of the dissertation to the chair of the examination committee, who then presents it to the examination committee. A new meeting of the examination committee is only required if one or more members reports a (new) problem regarding the revised text. As a rule, the members of the examination committee may express their opinion on the acceptability of the revised part/parts of the dissertation via e-mail. They must do so before the deadline determined during the initial meeting of the examination committee.</li>\r\n<li>Non placet nisi corrigatur: In the event of an evaluation of non placet nisi corrigatur, the following procedure is to be followed. Immediately after the examination committee has concluded its deliberations, the chair of the examination committee informs the researcher of this decision. Within a week, the supervisor and correctors provide the researcher with a joint written report in which the readers\' evaluation is thoroughly explained and which presents the requirements for the revision of the dissertation. On the basis of this report, the researcher reworks the dissertation during a period of maximum six months.</li>\r\n<li>When the researcher is of the opinion that the revised dissertation meets the stated requirements, he/she may, with the written agreement ofthe supervisor(s) (and, if necessary, the co-supervisor(s)), resubmit the dissertation and the revised summary and list of annexed theses to the chair of the examination committee, who then presents it to the members of the examination committee. As a rule, the committee meets again after a maximum of six weeks to deliver a definitive evaluation on the acceptability of the work. All members are expected to electronically submit, within the predetermined time, a supplementary report with a motivated final evaluation to the research secretariat for the attention of the chair of the examination committee. The final evaluation can only be placet (accepted) or non placet (not accepted).</li>\r\n</ol>\r\n<strong>&sect;4</strong>. In the case of a placet, the chair of the examination committee will immediately inform the researcher of this decision. In the case of a non placet, the non-acceptance of the dissertation is explained to the researcher by the chair and the members of the examination committee.<br /><br /><br />\r\n<h4 style=\"text-align: center;\"><strong>Public Defence</strong></h4>\r\n<strong><br />&sect;1</strong>. Between the examination committee and the public defence, there is a period of maximum six weeks. The researcher finalises the text of the dissertation, has it bound, and delivers six bound (book format, recto verso) copies (in case of a co- supervisor, seven copies) of the dissertation at the research secretariat. Each of the bound copies contains at the front a signed original Declaration of Originality/Plagiarism Declaration. At the same time he/she electronically submits a summary and his/her list of theses to the research secretariat. He/she uploads a PDF-file of the final version (via ALPHA INSTITUTE), after he/she has enrolled for the research defence at the ALPHA INSTITUTE student administration. The proof of submission of the dissertation, both printed and electronic, serves as the official admission to the public defence.<br /><br /><strong><br />&sect;2</strong>. As a rule, the supervisor(s) (and, if applicable, the co-supervisor(s)) and the correctors receive a definitive bound copy of the dissertation ten days before the defence. Before this date, the dissertation must also be electronically archived via ALPHA INSTITUTE. The candidate discusses the mode of accessibility of the research dissertation in Urias with his/her supervisor.<br /><br /><strong>&sect;3</strong>. The supervisor(s) (and, if applicable, the co-supervisor(s)) and the correctors are to submit their individual evaluation of the submitted dissertation in writing to the research secretariat for the attention of the chair of the examination committee, at the latest two working days before the defence. This evaluation applies to the work in its definitive form and is expressed in the form of a mark out of a total of twenty points.<br /><br /><strong>&sect;4</strong>. As a rule, the public defence of the dissertation and the annexed theses takes place in the Promotion Hall or the faculty\'s conference room within six weeks after the placet has been granted by the examination committee. Defences can take place from the beginning of the third examination period upto and including the day oft he proclamation oft he second ordinary examination period.<br /><br /><br /><strong>&sect;5.</strong> The public defence proceeds as follows:<br /><br />\r\n<ol>\r\n<li>First, the candidate gives, in a fifteen minute presentation, the main research results. The supervisor then presents a fifteen minute evaluation and laudatio. In the event that there is a co-supervisor, he/she may arrange with the supervisor to offer an evaluation of the dissertation within the time allotted to the supervisor(s). The three correctors are each allotted about fifteen minutes for discussion with the candidate.</li>\r\n<li>A brief summary of the dissertation together with the theses is made available to the public.</li>\r\n<li>After the defence, the examination committee adjourns for deliberation. The examination Ccommittee determines a mutually-agreed-upon mark. This mark is given based on the dissertation in its definitive form and the defence. The sum of this mutually-agreed-upon mark and the individual evaluations of the supervisor(s) (and, if necessary, the co-supervisor(s)) and the correctors expresses the final result. This result is expressed as a percentage. No grade is awarded.</li>\r\n<li>Research in Religious Science: The chair of the examination committee announces the promotion to Research in Religious Science.</li>\r\n<li>Within one month after the promotion, the newly promoted Researcher receives a letter with the percentage obtained, pending the finalisation of the official documents associated with the official degree.</li>\r\n</ol>\r\n&sect;6. The examination committee deliberates immediately after the public session and decides whether or not the Candidate can be awarded the degree of Doctor in Religious Science (DRS).&nbsp;<br /><br />A report is drafted and signed by all members of the examination committee present. The result is announced in public immediately after the deliberation.<br /><br />\r\n<h4 style=\"text-align: center;\"><strong>Appeal procedure</strong></h4>\r\n<strong>&sect;1</strong>. According to the procedure below an appeal is possible against the following decisions of the valuation committee and the examination committee (Higher Education CodexArt.1.3 69&deg;):<br /><br />\r\n<ol>\r\n<li>the discontinuation of the reseach programme,</li>\r\n<li>the discontinuation of the preparation oft he thesis,</li>\r\n<li>the final result of the public defence.</li>\r\n</ol>\r\n<strong>&sect;2</strong>. A&nbsp; researcher who judges that a decision as mentioned above has breached his/her rights, can launch an internal appeal with the Vice Rector for Student Affairs. The&nbsp; researcher is informed of this possibility. If the Vice Rector for Student Affairs is an interested party, he/she is replaced by the Vice Rector for Research Policy.<br /><br /><strong>&sect;3</strong>. The&nbsp; researcher must submit the appeal by e-mail within five calendar days from the day after which the decision of the valuationcommittee or the examination committee was made known. In his/her complaint the&nbsp; researcher includes at least a factual description of the invoked objections.<br /><br /><strong>&sect;4</strong>. The Executive Director for Student Affairs hears all parties in question and in each case the&nbsp; researcher. The internal appeal procedure results in:<br />\r\n<ol>\r\n<li>The motivated rejection of the appeal on grounds of unacceptability or unsubstantiated claims. This decision is brought to the attention of the&nbsp; researcher by e-mail within fifteen calendar days from the day after which the internal appeal was launched.</li>\r\n<li>A new decision by the Vice Rector for Student Affairs. The Vice Rector together with the Research coordinator of the group in question or the ZAP member appointed by him/her tries to find a solution. If no consensus can be reached, the Vice Rector takes an autonomous decision. The new decision must be taken within fifteen calendar days, starting from the day after the internal appeal was launched with the Vice Rector for Student Affairs and is also made known to the&nbsp; researcher within this period. The e-mail address which the&nbsp; researcher used to submit his/her appeal is used forth is purpose.</li>\r\n<li>&nbsp;</li>\r\n</ol>\r\n<h4 style=\"text-align: center;\">Marks and Grading System</h4>\r\n<strong>&sect;1</strong>. The grade is determined taking into consideration the aggregate of the marks obtained from the Seminars, Courses, and the Dissertation in the following proportions: <br /><br />Research Papers, Seminars and other courses&nbsp; &nbsp; &nbsp;:&nbsp; &nbsp; &nbsp;20%<br />Written Dissertation&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; :&nbsp; &nbsp; &nbsp;60%<br />Public Defense&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; :&nbsp; &nbsp; &nbsp;20%<br /><br /><br /><strong>&sect;2</strong>.Grading of the Research Programme will be as follows:<br /><br />\r\n<table style=\"border-collapse: collapse; width: 46.1233%; height: 105px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 17.1968%; height: 18px; text-align: center;\">40%</td>\r\n<td style=\"width: 20.4772%; height: 18px; text-align: center;\">Pass Mark</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 17.1968%; height: 18px; text-align: center;\">41%-59%</td>\r\n<td style=\"width: 20.4772%; height: 18px; text-align: center;\">Third Class</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 17.1968%; height: 18px; text-align: center;\">60%-69%</td>\r\n<td style=\"width: 20.4772%; height: 18px; text-align: center;\">Second Class</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 17.1968%; height: 18px; text-align: center;\">70%-84%</td>\r\n<td style=\"width: 20.4772%; height: 18px; text-align: center;\">First Class</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 17.1968%; height: 18px; text-align: center;\">85% and above</td>\r\n<td style=\"width: 20.4772%; height: 18px; text-align: center;\">Distinction</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<br />\r\n<h4 style=\"text-align: center;\">&nbsp;</h4>','3-7 Years','Please contact Alpha Office. (08086312826)','research-in-religious-science-drs-1','user_files/course/9dcc3c0382d86e721f44784a4e49b0f4.jpg','','','2020-03-19 03:30:53','2025-06-04 07:16:23');
