INSERT INTO `downloads` VALUES (2,1,'Guidelines- For writing Thesis and Assignments.',NULL,'user_files/downloads/6ec74980f9cac1851f1bbf89bffc12f3.pdf','2020-04-12 04:34:30','2021-08-04 06:35:19'),(5,1,'Form Progress Report – Doctoral Research',NULL,'user_files/downloads/4d563a0f2897e25c6c307af358e4ef93.docx','2020-04-12 04:38:32','2020-04-17 12:31:02'),(9,1,'Major Areas of Research',NULL,'user_files/downloads/39d364a45f18d6aded44b9b57eeece1b.pdf','2020-04-12 04:50:26','2020-04-17 12:32:13'),(24,1,'Thesis-Front Page',NULL,'user_files/downloads/895918bf42c9cf645345c795e3c17816.pdf','2020-07-09 04:41:38','2025-06-09 04:52:28'),(25,1,'Assignment: Front Page',NULL,'user_files/downloads/4a0f82a5eae3f673e61bf4113ec1feef.pdf','2020-07-09 04:45:39','2025-06-09 05:01:28'),(28,1,'Alpha Application Form',NULL,'user_files/downloads/1a6d9d85ba0c24039e25b691d344e651.pdf','2020-07-24 10:14:11','2020-07-24 10:14:11'),(29,1,'2025-2026 - BTh Syllabus',NULL,'user_files/downloads/6c59b4d3fb704ee12dcb5b7cc3134567.pdf','2020-07-30 04:51:53','2025-06-09 04:33:01'),(47,1,'Introduction to Theology_PPT',NULL,'user_files/downloads/8f153b196cd9178ea284c1f66db4362a.pdf','2020-08-08 04:07:00','2020-08-08 04:07:00'),(60,4,'Introduction to Theology Presentation (English)',NULL,'user_files/downloads/7addeeeb70e97bfe8581cfa2ee7211a4.pdf','2020-09-11 04:40:37','2020-09-11 04:41:39'),(228,4,'Introduction to Theology (Malayalam)',NULL,'user_files/downloads/74c1a198ab0ecd5d2bff49ee2c9db2be.pdf','2021-07-31 04:18:35','2021-07-31 04:18:35'),(233,4,'Introduction to Theology (English)',NULL,'user_files/downloads/be324b4b7a6f97e8af457abe245f9235.pdf','2021-07-31 04:22:24','2021-07-31 04:22:24'),(287,1,'MTH Syllabus 2025-2026',NULL,'user_files/downloads/2d74e7ddaf09a37f34ab997e633d5c15.pdf','2025-06-09 05:04:08','2025-06-09 05:04:34'),(288,4,'Theological Anthropology (English)',NULL,'user_files/downloads/834dbd44efbae9714e5d0f246695b22f.pdf','2025-07-23 10:31:35','2025-07-23 10:31:35'),(289,4,'Theological Anthropology (Malayalam)',NULL,'user_files/downloads/32a8240d6e1a4b0c9a03c9eb679614da.pdf','2025-07-23 10:32:16','2025-07-23 10:32:16'),(290,4,'Sacramental Theology (Malayalam)',NULL,'user_files/downloads/97abe21535e3f628f1e41d2ef05c865a.pdf','2025-07-23 10:55:50','2025-07-23 10:55:50'),(291,4,'Sacramental Theology (Eng)',NULL,'user_files/downloads/e4f992e7cb1d2aa0e49d449526713bf9.pdf','2025-07-23 11:00:04','2025-07-23 11:00:04'),(292,4,'Eschatology(English)',NULL,'user_files/downloads/efb87909797f0c3764a9667ddc7b6f82.pdf','2025-07-23 11:06:13','2025-07-23 11:06:13'),(293,4,'Eschatology (Malayalam)',NULL,'user_files/downloads/5e580300ebe2bca015047c4ae474e9f6.pdf','2025-07-23 11:07:22','2025-07-23 11:07:22'),(294,4,'Christology (Malayalam)',NULL,'user_files/downloads/fb7f978a32a9c3590103f4736745f9a1.pdf','2025-07-23 11:08:07','2025-07-23 11:08:07'),(295,4,'Christology (English)',NULL,'user_files/downloads/968d7af405cb2c8d564d7b6de85758b9.pdf','2025-07-23 11:18:33','2025-07-23 11:18:33');
