INSERT INTO `faqs` VALUES (12,'Can I learn theology in Malayalam?','<p>Yes, you can. Alpha provides two study program: in Malayalam and in English. Candidates can follow either of them.</p>','2020-04-12 04:26:18','2020-04-12 04:26:18'),(13,'How do I attend Masters Degree program?','<p>Masters Degree Students are required to attend contact class at Thalassery and write their exams in the allotted study centers.</p>','2020-04-12 04:26:40','2020-04-12 04:26:40'),(14,'How can I apply for revaluation?','<p>Revaluation request must be placed through email. Revaluation is done after having fulfilled the necessary requirements by the candidate.</p>','2020-04-12 04:27:01','2020-04-12 04:27:01'),(15,'How can I access the Library?','<p>You can browse online to know the availability of the books at Alpha Library. Since it is a reference library, the books are not available to loan.</p>','2020-04-12 04:27:22','2020-04-12 04:27:22'),(16,'How can I download Model Questions?','<p><br />You have to login into your student page with your Username [Register number] and Password. Then click on <strong>Model Questions.</strong>&nbsp;</p>','2020-04-12 04:29:07','2020-04-12 04:29:07'),(17,'I am an old student. I could not complete my course. How can I continue my studies?','<p>If you are within first five years of registration, you can contact the office and get information how to continue your studies.</p>','2020-04-12 04:29:31','2020-04-12 04:29:31'),(18,'Can I change my study centre?','Yes. You can. But with the prior consent from the Dean of Studies.','2020-04-12 04:29:54','2020-04-12 04:29:54'),(19,'What is the mode of exam?','<p>Alpha provides two modes of exam: written and online. Online exam is meant for the student who cannot reach to one of our study centers. Finally, it rests on the Controller of Examinations to decide to allow a candidate to do the exam online.</p>','2020-04-12 04:30:11','2020-04-12 04:30:11'),(20,'Are there age limitations to attend BTh/MTh/IMA?','No.','2020-04-12 04:30:35','2020-04-12 04:30:35'),(21,'What are the minimum qualifications for admission?','<p>For MTh/IMA: In the case of MTh the candidate must have a bachelors&nbsp;<em>degree</em>&nbsp;in Theology with a minimum of 55 percent marks. In the case of Integrated Masters Degree, Masters Degree in any other secular sciences (2 year program) with a minimum of 55 percent mark.</p>\r\n<p>For Bachelor&rsquo;s Degree in the theology, the candidate must have a +2 certificate with minimum 55 percent mark.</p>','2020-04-12 04:30:57','2020-04-12 04:30:57'),(22,'How can I apply for Bachelor of Theology, Masters of Theology or Integrated Masters Degree in Theology?','<p>Aspiring candidate can download the application form the website of alpha, <a href=\"http://www.alphathalassery.org\">www.alphathalassery.org</a> and send to the office via email or by post. The candidate can register for the course in the office itself. Almost all&nbsp;applications&nbsp;are received and processed on a running basis by the Admissions Office of Alpha. You will be notified when the admission procedure is finished.</p>','2020-04-12 04:31:26','2020-04-12 04:31:26');
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

