INSERT INTO `libraries` VALUES (11,'ALPHA LIBRARY CATALOGE','<ol>\r\n<li><strong>Alpha Central Library at Thalassery:</strong>&nbsp;The Students can make use of the library facilities available at alpha research center.</li>\r\n<li><strong>Collaborating Libraries:&nbsp;</strong>Besides the library facilities available at the Alpha Center, the research scholars of the Apha centre will have access to the following nationally reputed libraries of the various theological centers allover India. The tie-up made between the Alpha Centre and these Institutions make the mutual sharing of the library and Infrastructure facilities</li>\r\n</ol>\r\n<ul>\r\n<li><strong><em>St. Joseph&rsquo;s Pontifical Library, Alwaye</em></strong>&nbsp;&ndash; More than 80000 Books in Christian Theology and Asian Christian Studies</li>\r\n<li><em><strong>St. Thomas Paurasthya Vidhyapeedam Library, Kottayam</strong></em>&nbsp;&ndash; More than 70000 Books in various branches of Christian Theology.</li>\r\n<li><strong><em>Good Shepherd Major Seminary Library, Kunnoth, Kannur</em>&nbsp;</strong>&ndash; More than 30000 books on various branches of Christian Theology.</li>\r\n<li><em><strong>Jnanadeepa Vidya Pidam, Pune</strong></em>&nbsp;&ndash; More than 100000 Books on various branches of Christian Theology in English, French, German, Italian Languages</li>\r\n<li><em><strong>Dharmaram Vidykshetra Library</strong></em>&nbsp;&ndash; More than 100000 Books on various branches of Christian Theology in English, French, German, Italian Languages</li>\r\n</ul>','alpha-library-cataloge-1','2020-04-14 07:03:13','2020-04-25 04:42:44');
/*!40000 ALTER TABLE `libraries` ENABLE KEYS */;
UNLOCK TABLES;

