INSERT INTO `news` VALUES (20,'BTh Syllabus 2025 Batch','<p><strong>First Semester</strong></p>\r\n<ol>\r\n<li>Introduction to Theology</li>\r\n<li>The Gospel of St. John</li>\r\n<li>Salvation History: Ezra Nehemiah</li>\r\n<li>Dogmatic Theology Trinity</li>\r\n<li>Biblical Greek &ndash;I</li>\r\n<li>Seminar: Theological Relevance of Antiqum Ministerium</li>\r\n</ol>\r\n<p>&nbsp;</p>\r\n<p><strong>Second Semester</strong></p>\r\n<ol>\r\n<li>The Gospel of St. Mathew</li>\r\n<li>Theology of Pentateuch</li>\r\n<li>Mariology</li>\r\n<li>Biblical Hebrew &ndash;I</li>\r\n<li>Patrology</li>\r\n</ol>\r\n<p><strong>&nbsp;</strong></p>\r\n<p><strong>Third Semester</strong></p>\r\n<ol>\r\n<li>Sacraments in General</li>\r\n<li>Theological Anthropology</li>\r\n<li>Eschatology</li>\r\n<li>Christology</li>\r\n<li>Seminar:&nbsp;</li>\r\n</ol>\r\n<p>&nbsp;</p>\r\n<p><strong>Fourth Semester</strong></p>\r\n<ol>\r\n<li>The Gospel of St. Mark</li>\r\n<li>Canon Law</li>\r\n<li>Ecclesiology</li>\r\n<li>Liturgy - Various Rites</li>\r\n<li>Assignment: Interpretation of Lord\'s Prayer</li>\r\n</ol>\r\n<p>&nbsp;</p>\r\n<p><strong>Fifth Semester</strong></p>\r\n<ol>\r\n<li>The Gospel of St. Luke</li>\r\n<li>Social Doctrines of the Church</li>\r\n<li>General Church History</li>\r\n<li>Fundamental Moral Theology</li>\r\n<li>Seminar: Contemporary ethical reading of Decalogue</li>\r\n</ol>\r\n<p>&nbsp;</p>\r\n<p><strong>Sixth Semester&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </strong></p>\r\n<ol>\r\n<li>Indian Church History I</li>\r\n<li>Pauline Theology</li>\r\n<li>Political Theology</li>\r\n<li>Biblical Hermeneutics</li>\r\n<li>BTh Dissertation</li>\r\n</ol>','bth-syllabus-2025-batch','2020-09-01 05:39:58','2025-07-10 08:43:05'),(23,'Final Year Students - Fee Details','All the final year students (BTh/MTh) are requested to clear the pending fees before 30th July 2025.','final-year-students-fee-details-1','2020-09-24 05:15:13','2025-07-10 08:42:19'),(26,'Alpha Office Contact Numbers','<strong><br />Mobile&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - 8086312826<br /></strong>','alpha-office-contact-numbers-1','2020-09-25 09:11:13','2025-07-10 08:41:41'),(46,'Thesis Guidelines','<ol>\r\n<li>Thesis must be written in a systematic way according to the methodology suggested by the Institute. The methodological guidelines are published on the website (downloads page) of the Alpha Institute.</li>\r\n<li>The cover page of every thesis shall have the format approved by the Institute. It can be downloaded from our website (downloads page).&nbsp;</li>\r\n<li>Thesis must be submitted to the office of the Institute on or before the date suggested for.</li>\r\n</ol>\r\n<p><strong>BTh Dissertation&nbsp; : </strong>50-80&nbsp;pages, Binding copy, note the guidelines provided in the website.</p>\r\n<p><strong>MTh Dissertation :</strong> It&nbsp;must be typed.&nbsp;80-100 pages, Binding copy (2).</p>','thesis-guidelines','2021-03-02 05:36:58','2021-03-02 05:36:58'),(55,'BTh/ MTh Thesis Last Date Announced','All the final year students are requested to submit the final year thesis on or before 30th june 2025.&nbsp;<br />\r\n<ul>\r\n<li>BTh students should submit one hardcopy&nbsp;</li>\r\n<li>MTh students should submit two hard copies&nbsp;</li>\r\n</ul>\r\nFor more details visit downloads - Thesis Guidelines.','bth-mth-thesis-last-date-announced-1','2022-02-22 04:41:55','2025-07-10 08:44:12');
/*!40000 ALTER TABLE `news` ENABLE KEYS */;
UNLOCK TABLES;

