INSERT INTO `professors` VALUES (4,'Bishop Joseph Pamplany','<strong>(Co-Patron)<br />Academic Profile: <br /></strong>\r\n<ul>\r\n<li>MA (Religious Studies), KU Leuven</li>\r\n<li>Licentiate in Sacred Scripture, KU Leuven&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</li>\r\n<li>PhD ( Sacred Scripture), KU Leuven</li>\r\n<li>PG Diploma in German, Hebrew, Greek</li>\r\n<li>Authorship: 28 Books, 84 Scientific Articles</li>\r\n<li>Chief Editor: Alpha Bible Commentary, Alpha Theological Commentary</li>\r\n<li>Editor: of three academic journals</li>\r\n<li>Teaching Experience: Since 2006</li>\r\n<li>Number of PhD guided: 5</li>\r\n</ul>','user_files/professors/30c8d20b7a6bd4f6bc09fefe4074f863.jpg','2020-04-13 13:24:01','2020-07-10 10:58:46'),(7,'Dr. Philip Kaviyil','<strong>(President - Alpha Institute)<br />Academic Profile: </strong><br />\r\n<ul>\r\n<li>MA(New Testament) , Peter&rsquo;s Pontifical Institute Bangalore</li>\r\n<li>PhD (Bible) University of Innsbruck</li>\r\n<li>Language Studies (German) Leopold-Franzens- University Innsbruck &ndash; Austria</li>\r\n<li>Authorship: 1 Book, 10 Articles</li>\r\n<li>Teaching Experience: Since 2014</li>\r\n</ul>','user_files/professors/0e1912b67557f2cd8835b1e642e04dbb.jpg','2020-04-18 03:48:53','2020-09-11 04:42:05'),(8,'Dr. Bincy Mathew S.H','<strong>Academic Profile:<br /></strong>\r\n<ul>\r\n<li>MA (Religious studies), KU Leuven, Belgium</li>\r\n<li>Lientiate in Pastoral Theology, KU Leuven</li>\r\n<li>PhD ( Sacred Scripture) KU Leuven</li>\r\n<li>PG Diploma in Greek, Hebrew</li>\r\n<li>Authorship 3 Books, 30 Scientific articles</li>\r\n<li>Teaching Experience - Since 2016</li>\r\n<li>No. Phd guided - 2</li>\r\n</ul>','user_files/professors/c6f851abaf93976240b7909fd2c5d05c.jpg','2020-04-18 03:52:24','2021-10-14 06:31:03'),(9,'Rev. Fr . Kuriakose Karakkattu','<strong>(Asst. Director - Alpha)<br />Academic Profile: </strong><br />\r\n<ul>\r\n<li>B A Philosophy- Mahatma Gandhi University, Kottayam&nbsp;</li>\r\n<li>Bph:Paurastya Vidyapitham Kottayam</li>\r\n<li>BTh:&nbsp; Pontifical Urban University Rome&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</li>\r\n<li>MA(Biblical Theology), Pontifical Urban University Rome&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</li>\r\n<li>Teaching experience : Since 2016</li>\r\n</ul>','user_files/professors/4f29126504b56406f037a10602fb2837.jpg','2020-04-18 03:59:23','2020-04-29 04:35:22'),(10,'Rev. Fr. Joseph Kakkaramattathil','<strong>(Controller of Examinations - Alpha)<br />Academic Profile: <br /></strong><br />\r\n<ul>\r\n<li>BPh : Paurastya Vidyapitham Kottayam</li>\r\n<li>BTh : Paurastya Vidyapitham Kottayam&nbsp;</li>\r\n<li>Licentiate in Theology Dogmatic :&nbsp; InstitutCatholique de Paris</li>\r\n<li>Pr&eacute;-doctorate : InstitutCatholique de Paris</li>\r\n<li>Teaching Experience : Since 2009&nbsp;</li>\r\n</ul>','user_files/professors/bb2d7e0105262b7326e72f4e7d827d6d.jpg','2020-04-18 04:13:53','2020-09-11 04:42:41'),(11,'Dr. Thomas Kochukarottu','<strong>Academic Profile: </strong><br />\r\n<ul>\r\n<li>M.Phil(Dogmatic Theology), Holy Cross University, Rome&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</li>\r\n<li>PhD (Dogmatic Theology). Urban University, Rome</li>\r\n<li>Language Studies: G. Diploma (1 year, German), St. Thomas Aquinas University, Rome</li>\r\n<li>Authorship: 7 books and 5 Articles</li>\r\n<li>Editor: Managing Editor-<em>Alpha Bible Commentary</em>, Managing Editor- <em>The Shepherd</em> , Managing Editor-Religious Text Book</li>\r\n<li>Teaching Experience: Since 2007</li>\r\n</ul>','user_files/professors/b2c13f1c8e4ddda8393ed7ed41af01f7.jpg','2020-04-18 04:20:06','2020-04-18 04:20:06'),(12,'Dr. George Kanjirakkattu','<strong>Academic Profile: </strong><br />BPh : Paurastya Vidyapitham Kottayam&nbsp;<br />BTh : Paurastya Vidyapitham Kottayam&nbsp;<br />MTh : Pontificia Universit&agrave; della Santa Croce Rome<br />PhD : (Church History), Pontificium Institutum Orientale Rome<br />Authorship : 3 Books','user_files/professors/da1aa179ad28013b18476305b54b436c.jpg','2020-04-18 04:30:39','2020-05-10 07:40:18'),(13,'Dr. Siju Augustine Vennayappillil','<strong>Academic Profile: </strong><br />\r\n<ul>\r\n<li>BPh : Paurastya Vidyapitham Kottayam</li>\r\n<li>BTh : Paurastya Vidyapitham Kottayam</li>\r\n<li>MTh: Pontifical Urban University Rome</li>\r\n<li>PhD (Biblical Theology):Pontifical Urban University Rome</li>\r\n<li>PG Diploma in Hebrew, Greek</li>\r\n<li>Language Studies: G. Diploma (1 year, German), &Ouml;sterreich Institut Roma ; Italian (advanced)&nbsp;Pontifical Urban University Rome</li>\r\n<li>Authorship: 2 books and 5 Articles</li>\r\n<li>Chief Editor: Ajapalakan (2017-18)</li>\r\n<li>Teaching Experience: Since 2017</li>\r\n</ul>','user_files/professors/25bb6435304acf81895621d0d608ff39.jpg','2020-04-18 04:37:53','2020-05-10 07:40:46'),(14,'Dr. Sajan Thomas Thengumpally','<strong>Academic Profile: </strong><br />\r\n<ul>\r\n<li>MA (Canon Law) Dharmaram Vidya Kshetram, Bangalore</li>\r\n<li>Authorship: 2 Books.</li>\r\n<li>4 Research Articles in National and International Publications</li>\r\n<li>Courses taught at different Major Seminaries and Institutes: Canon law</li>\r\n</ul>\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p>','user_files/professors/7993db78d076fe2be331215205adf78d.jpg','2020-05-10 07:39:21','2020-05-10 07:39:21'),(15,'Rev. Dr. Augustine Thomas Pamplaniyil','<ul>\r\n<li>M.Ph.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;:&nbsp; Jnanadeepa Vidyapeeth, Pune&nbsp;&nbsp;</li>\r\n<li>M.Sc.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: (Psychology) Madras University&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</li>\r\n<li>M.A.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Erasmus Mundus Master in Bioethics&nbsp; Katholieke Universiteit, Leuven Belgium.</li>\r\n<li>Ph.D (Philosophy)&nbsp; &nbsp;: Open International University, Columbo</li>\r\n<li>Authorship&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;:&nbsp; 7 Books &amp; 11 Articles</li>\r\n<li>Teaching Experience : Since 2000</li>\r\n</ul>','user_files/professors/863d617d355c282b21d9a14056f59cd2.jpg','2020-05-11 04:34:43','2020-05-11 04:34:43'),(16,'Dr. Tom Olikkarott','<strong>(Executive Director)<br />Academic Profile: <br /></strong>\r\n<ul>\r\n<li>Ph.D. Pontifical Biblical Theology from St. Thomas Aquinas University, Rome</li>\r\n<li>Licentiate from Pontifical Urban University Rome in Biblical Theology</li>\r\n<li>Authorship: 3 books, 12 Articles</li>\r\n<li>Teaching experience, 2010 onwards</li>\r\n</ul>','user_files/professors/9119ca1bcfdd1278dabbaefbc1801f86.jpg','2020-10-13 11:18:18','2021-03-27 09:55:21'),(17,'Dr. Jisi Maria CMC','<strong>(Controller of Examinations)<br />Academic Profile: <br /></strong>\r\n<ul>\r\n<li>Ph.D. Theology of Consecrated Life from Pontifical Lateran University, Claretianoum, Roma</li>\r\n<li>Authorship: 2 books, 15 Articles</li>\r\n<li>Teaching experience, 2016 onwards</li>\r\n</ul>','user_files/professors/848c1ad7268c651ad8cb00fd00cf2d5f.jpg','2021-10-14 06:03:17','2021-10-14 06:07:19');
