INSERT INTO `publications` VALUES (1,1,'ആൽഫ ബൈബിൾ വ്യാഖ്യാനം - Alpha Bible Commentary (ABC-8 Volume)','alpha-bible-commentary-abc-8-volume-1','<ul>\r\n<li>മലയാളഭാഷയില്&zwj; ആദ്യമായി സമ്പൂര്&zwj;ണ്ണ ബൈബിളിന്&zwj;റെ വ്യാഖ്യാനം.</li>\r\n<li>സമ്പൂർണ്ണ ബൈബിളിലെ 73 പുസ്തകങ്ങളും ശാസ്ത്രീയവും അജപാലനപരവുമായി വിശദീകരിക്കുന്നു.</li>\r\n<li>കേരളസഭയിലെ പ്രഗത്ഭരായ 35 ബൈബിള്&zwj; പണ്ഡിതരുടെ സംയുക്ത സംരംഭം</li>\r\n</ul>','മലയാളം','7000 + Postal Charge','user_files/publications/58d3829b1fefefe392f6ed689309607f.jpg','2020-02-13 11:41:05','2025-06-09 04:18:33'),(2,1,'ആൽഫ ദൈവശാസ്ത്ര വ്യാഖ്യാനം','-8','-ക്രിസ്തീയ ദൈവശാസ്ത്രത്തിന്&zwj;റെ അടിസ്ഥാന വിഷയങ്ങള്&zwj; സമഗ്രമായി അപഗ്രഥിക്കുന്ന മലയാളത്തിലെ ആദ്യത്തെ സമ്പൂര്&zwj;ണ്ണ ദൈവശാസ്ത്ര ഗ്രന്ഥാവലി (33 വാല്യങ്ങള്&zwj;).<br />-എക്യുമെനിക്കല്&zwj; ദൈവശാസ്ത്രശൈലി.<br />-വി. ഗ്രന്ഥം, സഭാപിതാക്കന്മാർ, മൗലിക ദൈവശാസ്ത്രം , ധാർമ്മിക ദൈവ ശാസ്ത്രം, കൗദാശിക ദൈവശാസ്ത്രം, ആരാധന ക്രമം തുടങ്ങിയ മേഖലകളെ അപഗ്രഥിക്കുന്നു.','മലയാളം','3500 + Postal Charge','user_files/publications/354c74fd0bdd73bb46d187a4a99d9b4b.jpg','2020-03-28 06:08:36','2025-06-09 04:18:54'),(4,1,'ബൈബിള്‍ ശബ്ദകോശം (Bible Dictionary)','bible-dictionary-1','സമ്പൂര്&zwj;ണ്ണ ബൈബിളിലെ സമസ്തപദങ്ങളുടെയും സമഗ്രവും ആധികാരികവുമായ പഠനമാണ് ഈ നിഘണ്&zwj;ുവില്&zwj; ഉള്&zwj;പ്പെടുത്തിയിട്ടുളളത്. ഇതൊരു ബഹുഭാഷാ നിഘണ്&zwj;ുവാണ്.ഓരോ മലയാള പദത്തിന്&zwj;റെയും ഇംഗ്ലീഷ്, ഗ്രീക്ക്, ഹീബ്രു സമാനപദങ്ങള്&zwj; അതാത് ലിപികളില്&zwj; നല്&zwj;കിയിട്ടുണ്ട് .ഇത്തരമൊരു ചതുര്&zwj;ഭാഷാ നിഘണ്&zwj;ു മലയാള ഭാഷയില്&zwj; ആദ്യമായാണ് പുറത്തിറങ്ങുന്നത്.','Malayalam','750 + Postal Charge','user_files/publications/ea5a07047b0c5cf091c9b4fc818ffe57.jpg','2020-03-28 06:16:47','2020-04-11 05:07:09'),(5,1,'വിശ്വാസവും വ്യാഖ്യാനവും (Faith and Interpretation)','faith-and-interpretation-1','വിശ്വാസവും യുക്തിയും തമ്മിലുള്ള പാരസ്പര്യം ചിന്തികരെ എക്കാലവും കുഴക്കിയിട്ടുണ്ട്. വിശ്വാസം യുക്തിവിരുദ്ധമാണെന്ന ചിന്തയെ തിരുത്തിക്കൊണ്ട് യുക്തിക്കു മനസ്സിലാക്കുവാന്&zwj; വേണ്ടിയാണ് വിശ്വസിക്കുന്നത് എന്ന് വി. ആന്&zwj;സലേമും വിശ്വാസമെന്നത് യുക്തിയോടുളള തുറവിയാണെന്ന് വി. അഗസ്റ്റിനും വാദിക്കുന്നുണ്ട്.<br />വിശ്വാസത്തെ യുക്തികൊണ്ട് വിശദീകരിക്കാനല്ല വിശ്വാസം യുക്തിഭദ്രമാണെന്ന് വിലയിരുത്താനാണ് അജപാലനത്തിന്&zwj;റെ വഴിത്താരയും കണ്ടതും കേട്ടതുമായ വിശ്വാസ പ്രതിസന്ധികള്&zwj;ക്ക് ഈ ഗ്രന്ഥം ഉത്തരം തേടുന്നത്.','Malayalam','160 + Postal Charge','user_files/publications/867b4aa1239f36c4d70cf02fe2f133ed.jpg','2020-03-28 06:18:38','2020-04-11 05:09:12'),(6,1,'ശ്രവണം','-6','ആത്മീയത എന്നത് കേള്&zwj;വിയോടുള്ള തുറവിയാണ്. ഏറ്റവും വലിയ ആത്മീയ അവയവം തലച്ചോറോ ഹൃദയമോ അല്ല; ചെവിയാണെന്ന തിരിച്ചറിവ് നമ്മെ ഏറെ ചിന്തിപ്പിക്കുന്നതാണ്. കേള്&zwj;ക്കാന്&zwj; സമയവും സന്നദ്ധതയും ഇല്ലാത്തവരുടെ ആധുനിക ലോകത്തില്&zwj; ശ്രവണത്തിന്&zwj;റെ ആധ്യാത്മികതയ്ക്ക് ഏറെ അര്&zwj;ത്ഥവ്യാപ്തി ഉണ്ട്. തിരുവചനം ശ്രവിച്ചതിന്&zwj;റെ സന്തോഷമാണ് ഈ ഗ്രന്ഥം.','Malayalam','230 + Postal Charge','user_files/publications/ea32d9e6170f89302c0bd2b793ac868c.jpg','2020-03-28 06:21:12','2020-04-11 05:23:42'),(7,3,'Pauline Letters & Theology','pauline-letters-theology-1','This text is mainly indented to initiate the reader to the unfathomable mysteries of Pauline theology explained through his letters','English','220 + Postal Charge','user_files/publications/48d73f433932355fe8a5d9d64a1431f6.jpg','2020-03-28 06:22:22','2020-04-11 05:16:17'),(8,1,'Alpha Theological Commentary (ATC)','alpha-theological-commentary-atc-1','<ul>\r\n<li>It is the first work in Malayalam that evaluates the fundamentals of Christian theology in its totality.</li>\r\n<li>In 33 Volumes Alpha Theological Commentary (ATC) provides an integral wisdom of the Catholic theology.</li>\r\n<li>It deals with various disciplines of theology like: Sacred Scripture, Fathers of the Church, Fundamental Theology, Moral Theology, Sacramental Theology etc.</li>\r\n</ul>','English','3500 + Postal Charge','user_files/publications/7c3aa35a4df6772b7eb817eb5ae19e78.jpg','2020-04-11 13:54:43','2025-06-09 04:18:05'),(9,1,'ഉപ്പ്','-7','\"അഭയശിലകൾ\" എന്ന ശീർഷകത്തിൽ ഇറക്കിയ വചന വ്യാഖ്യാന ഗ്രന്ഥത്തിന്റെ രണ്ടാം ഭാഗമാണ് \'ഉപ്പ്\'. <br />അവതാരം , സ്ത്രീ, വിശ്വാസം, മൂല്യങ്ങൾ, പീഡാനുഭവം,&nbsp; ഉത്&zwnj;ഥാനം, തിരുസഭ എന്നീ ഏഴു ഭാഗങ്ങളിലായി 40 ലേഖനങ്ങൾ ഇതിൽ അടങ്ങിയിരിക്കുന്നു.','മലയാളം','160 + Postal Charge','user_files/publications/0864ff567bc4bb4b795574d049cf45f7.jpg','2020-07-13 09:48:18','2020-07-13 09:48:18');
